#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k;
    cin >> n >> k;
    int H = n - k;
    vector<vector<int>> a(H, vector<int>(k));
    int upper = 0;
    for (auto &r : a)
        for (int &x : r) {
            cin >> x;
            upper = max(upper, x);
        }
    vector<int> order(k);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int x, int y) {
        int sx = 0, sy = 0;
        for (auto &r : a) {
            sx += r[x];
            sy += r[y];
        }
        return sx < sy;
    });
    vector<vector<int>> b = a;
    for (int h = 0; h < H; h++)
        for (int c = 0; c < k; c++)
            b[h][c] = a[h][order[c]];
    a = b;
    vector<int> prior(k, -1);
    for (int c = 0; c < k; c++)
        for (int j = 0; j < c; j++) {
            bool same = true;
            for (int h = 0; h < H; h++)
                if (a[h][c] != a[h][j])
                    same = false;
            if (same)
                prior[c] = j;
        }
    vector<int> floors(n);
    iota(floors.begin(), floors.end(), 0);
    stable_sort(floors.begin(), floors.end(),
                [&](int x, int y) { return min(x, n - 1 - x) < min(y, n - 1 - y); });
    using U = unsigned;
    U all = (1U << n) - 1;
    auto feasible = [&](int T) {
        vector<vector<vector<U>>> good(k, vector<vector<U>>(H, vector<U>(n)));
        for (int c = 0; c < k; c++)
            for (int h = 0; h < H; h++)
                for (int f = 0; f < n; f++)
                    for (int x = 0; x < n; x++)
                        if (abs(x - f) * a[h][c] >= T)
                            good[c][h][f] |= 1U << x;
        auto matching = [&](vector<U> mask) {
            sort(mask.begin(), mask.end(), [](U x, U y) {
                return __builtin_popcount(x) < __builtin_popcount(y);
            });
            U total = 0;
            for (int i = 0; i < H; i++) {
                total |= mask[i];
                if (__builtin_popcount(total) < i + 1)
                    return false;
            }
            vector<int> match(n, -1);
            U seen;
            function<bool(int)> dfs = [&](int u) {
                U bits = mask[u] & ~seen;
                while (bits) {
                    U bit = bits & -bits;
                    bits -= bit;
                    seen |= bit;
                    int v = __builtin_ctz(bit);
                    if (match[v] < 0 || dfs(match[v])) {
                        match[v] = u;
                        return true;
                    }
                }
                return false;
            };
            for (int h = 0; h < H; h++) {
                seen = 0;
                if (!dfs(h))
                    return false;
            }
            return true;
        };
        vector<int> placed;
        function<bool(int, const vector<U> &, U)> search =
            [&](int c, const vector<U> &mask, U used) {
                if (c == k)
                    return true;
                for (int f : floors) {
                    if ((used >> f & 1) || (c == 0 && f > (n - 1) / 2) ||
                        (prior[c] >= 0 && f <= placed[prior[c]]))
                        continue;
                    vector<U> next(H);
                    bool ok = true;
                    for (int h = 0; h < H; h++) {
                        next[h] = mask[h] & good[c][h][f] & ~(1U << f);
                        if (!next[h])
                            ok = false;
                    }
                    if (!ok || !matching(next))
                        continue;
                    placed.push_back(f);
                    if (search(c + 1, next, used | 1U << f))
                        return true;
                    placed.pop_back();
                }
                return false;
            };
        return search(0, vector<U>(H, all), 0);
    };
    int lo = 0, hi = upper + 1;
    while (lo + 1 < hi) {
        int mid = (lo + hi) / 2;
        if (feasible(mid))
            lo = mid;
        else
            hi = mid;
    }
    cout << lo << "\n";
}

