import sys

z = iter(map(int, sys.stdin.read().split()))
n, k = next(z), next(z)
H = n - k
A = [[next(z) for _ in range(k)] for _ in range(H)]
upper = max(map(max, A))
order = sorted(range(k), key=lambda c: sum(row[c] for row in A))
A = [[r[c] for c in order] for r in A]
vectors = [tuple(r[c] for r in A) for c in range(k)]
prior = [
    next((j for j in range(i - 1, -1, -1) if vectors[j] == vectors[i]), -1)
    for i in range(k)
]
candidates = sorted(range(n), key=lambda i: min(i, n - 1 - i))
allmask = (1 << n) - 1


def feasible(T):
    good = [[[0] * n for _ in range(H)] for _ in range(k)]
    for c in range(k):
        for h in range(H):
            need = (T + A[h][c] - 1) // A[h][c]
            for f in range(n):
                l = max(0, f - need + 1)
                r = min(n, f + need)
                good[c][h][f] = (
                    allmask ^ (((1 << (r - l)) - 1) << l) if r > l else allmask
                )
    placed = []

    def matching(masks):
        masks = sorted(masks, key=int.bit_count)
        union = 0
        for i, x in enumerate(masks):
            union |= x
            if union.bit_count() < i + 1:
                return False
        match = [-1] * n

        def dfs(u):
            nonlocal seen
            bits = masks[u] & ~seen
            while bits:
                bit = bits & -bits
                bits -= bit
                seen |= bit
                v = bit.bit_length() - 1
                if match[v] < 0 or dfs(match[v]):
                    match[v] = u
                    return True
            return False

        for i in range(H):
            seen = 0
            if not dfs(i):
                return False
        return True

    def search(c, masks, used):
        if c == k:
            return True
        for f in candidates:
            if (
                used >> f & 1
                or c == 0
                and f > (n - 1) // 2
                or prior[c] >= 0
                and f <= placed[prior[c]]
            ):
                continue
            g = good[c]
            available = allmask ^ (1 << f)
            nextm = [x & g[h][f] & available for h, x in enumerate(masks)]
            if not all(nextm) or not matching(nextm):
                continue
            placed.append(f)
            if search(c + 1, nextm, used | 1 << f):
                return True
            placed.pop()
        return False

    return search(0, [allmask] * H, 0)


lo, hi = 0, upper + 1
