#include <bits/stdc++.h>
using namespace std;
struct SparseMin {
    vector<vector<int>> table;
    vector<int> logarithm;
    SparseMin() = default;
    explicit SparseMin(const vector<int> &values) {
        int n = values.size();
        logarithm.resize(n + 1);
        for (int i = 2; i <= n; ++i)
            logarithm[i] = logarithm[i / 2] + 1;
        table.push_back(values);
        for (int width = 1; width * 2 <= n; width *= 2) {
            vector<int> row(n - width * 2 + 1);
            for (int i = 0; i < (int)row.size(); ++i)
                row[i] = min(table.back()[i], table.back()[i + width]);
            table.push_back(move(row));
        }
    }
    int get(int left, int right) const {
        int power = logarithm[right - left + 1];
        return min(table[power][left], table[power][right - (1 << power) + 1]);
    }
};
struct SuffixIndex {
    int n;
    vector<int> order, rank;
    SparseMin lcpMinimum;
    explicit SuffixIndex(const string &text) : n(text.size()), order(n), rank(n) {
        if (n == 1) {
            order[0] = rank[0] = 0;
            lcpMinimum = SparseMin(vector<int>{0});
            return;
        }
        iota(order.begin(), order.end(), 0);
        for (int i = 0; i < n; ++i)
            rank[i] = (unsigned char)text[i];
        for (int width = 1; width < n; width *= 2) {
            auto key = [&](int i) {
                return pair<int, int>{rank[i], i + width < n ? rank[i + width] : -1};
            };
            sort(order.begin(), order.end(),
                 [&](int a, int b) { return key(a) < key(b); });
            vector<int> nextRank(n);
            for (int at = 1; at < n; ++at)
                nextRank[order[at]] =
                    nextRank[order[at - 1]] + (key(order[at - 1]) != key(order[at]));
            rank.swap(nextRank);
            if (rank[order.back()] == n - 1)
                break;
        }
        vector<int> lcp(n);
        int common = 0;
        for (int i = 0; i < n; ++i) {
            int at = rank[i];
            if (at == 0) {
                common = 0;
                continue;
            }
            int j = order[at - 1];
            while (i + common < n && j + common < n &&
                   text[i + common] == text[j + common])
                ++common;
            lcp[at] = common;
            if (common)
                --common;
        }
        lcpMinimum = SparseMin(lcp);
    }
    int lce(int a, int b) const {
        if (a == b)
            return n - a;
        int left = rank[a], right = rank[b];
        if (left > right)
            swap(left, right);
        return lcpMinimum.get(left + 1, right);
    }
};
pair<string, int> solve(const string &text) {
    int n = text.size();
    SuffixIndex forward(text);
    string reversed = text;
    reverse(reversed.begin(), reversed.end());
    SuffixIndex backward(reversed);
    SparseMin rankMinimum(forward.rank);
    int bestCount = 1, bestLength = n, bestPosition = 0;
    for (int period = 1; period <= n / 2; ++period) {
        if (n / period < bestCount)
            break;
        for (int anchor = 0; anchor + period < n; anchor += period) {
            int right = forward.lce(anchor, anchor + period);
            int left = anchor ? backward.lce(n - anchor, n - anchor - period) : 0;
            int count = 1 + (left + right) / period;
            if (count < bestCount || (count == bestCount && period < bestLength) ||
                count < 2)
                continue;
            int first = anchor - left;
            int last = anchor + right - (count - 1) * period;
            int position = forward.order[rankMinimum.get(first, last)];
            if (count > bestCount || period > bestLength ||
                forward.rank[position] < forward.rank[bestPosition]) {
                bestCount = count;
                bestLength = period;
                bestPosition = position;
            }
        }
    }
    return {text.substr(bestPosition, bestLength), bestCount};
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string text;
    while (cin >> n >> text) {
        auto [unit, count] = solve(text);
        cout << unit << '\n' << count << '\n';
    }
}

