import sys


def sparse_min(values):
    table = [values]
    width = 1
    while width * 2 <= len(values):
        previous = table[-1]
        table.append(
            [
                min(previous[i], previous[i + width])
                for i in range(len(values) - width * 2 + 1)
            ]
        )
        width *= 2
    return table


def minimum(table, left, right):
    power = (right - left + 1).bit_length() - 1
    row = table[power]
    return min(row[left], row[right - (1 << power) + 1])


def suffix_index(text):
    n = len(text)
    if n == 1:
        return [0], [0], [[0]]
    order = list(range(n))
    rank = list(text)
    width = 1
    while width < n:
        order.sort(key=lambda i: (rank[i], rank[i + width] if i + width < n else -1))
        next_rank = [0] * n
        for at in range(1, n):
            a, b = order[at - 1], order[at]
            different = rank[a] != rank[b] or (
                (rank[a + width] if a + width < n else -1)
                != (rank[b + width] if b + width < n else -1)
            )
            next_rank[b] = next_rank[a] + different
        rank = next_rank
        if rank[order[-1]] == n - 1:
            break
        width *= 2
    lcp = [0] * n
    common = 0
    for i in range(n):
        at = rank[i]
        if at == 0:
            common = 0
            continue
        j = order[at - 1]
        while (
            i + common < n and j + common < n and text[i + common] == text[j + common]
        ):
            common += 1
        lcp[at] = common
        if common:
            common -= 1
    return order, rank, sparse_min(lcp)


def solve(text):
    n = len(text)
    order, rank, forward = suffix_index(text)
    _, reverse_rank, backward = suffix_index(text[::-1])
    rank_min = sparse_min(rank)

    def lce(a, b, ranks, table):
        if a == b:
            return n - a
        left, right = ranks[a], ranks[b]
        if left > right:
            left, right = right, left
        return minimum(table, left + 1, right)

    best_count, best_length, best_position = 1, n, 0
    for period in range(1, n // 2 + 1):
        if n // period < best_count:
            break
        for anchor in range(0, n - period, period):
            right = lce(anchor, anchor + period, rank, forward)
            left = (
                lce(n - anchor, n - anchor - period, reverse_rank, backward)
                if anchor
                else 0
            )
            count = 1 + (left + right) // period
            if count < best_count or count == best_count and period < best_length:
                continue
            if count < 2:
                continue
            first = anchor - left
            last = anchor + right - (count - 1) * period
            position = order[minimum(rank_min, first, last)]
            if (
                count > best_count
                or period > best_length
                or rank[position] < rank[best_position]
            ):
                best_count, best_length, best_position = count, period, position
    return text[best_position : best_position + best_length], best_count


if __name__ == "__main__":
    stream = sys.stdin.buffer
    for line in stream:
        if not line.strip():
            continue
        n = int(line)
        text = stream.readline().strip()
        unit, count = solve(text)
        print(unit.decode())
        print(count)

