#include <bits/stdc++.h>
using namespace std;
int main() {
    string a, b;
    getline(cin, a);
    getline(cin, b);
    long long L, K;
    cin >> L >> K;
    int n = a.size(), m = b.size();
    if (llabs(n - m) > L * K) {
        cout << "Impossible\n";
        return 0;
    }
    string s = a + char(1) + b;
    int N = s.size();
    vector<int> sa(N), rank(N), nr(N);
    iota(sa.begin(), sa.end(), 0);
    for (int i = 0; i < N; i++)
        rank[i] = (unsigned char)s[i];
    for (int gap = 1; gap < N; gap *= 2) {
        auto key = [&](int i) {
            return pair<int, int>{rank[i], i + gap < N ? rank[i + gap] : -1};
        };
        sort(sa.begin(), sa.end(), [&](int x, int y) { return key(x) < key(y); });
        nr[sa[0]] = 0;
        for (int j = 1; j < N; j++)
            nr[sa[j]] = nr[sa[j - 1]] + (key(sa[j]) != key(sa[j - 1]));
        rank = nr;
        if (rank[sa.back()] == N - 1)
            break;
    }
    vector<int> lcp(N);
    for (int i = 0, h = 0; i < N; i++) {
        int r = rank[i];
        if (!r)
            continue;
        int j = sa[r - 1];
        while (i + h < N && j + h < N && s[i + h] == s[j + h])
            h++;
        lcp[r] = h;
        if (h)
            h--;
    }
    vector<int> lg(N + 1);
    for (int i = 2; i <= N; i++)
        lg[i] = lg[i / 2] + 1;
    vector<vector<int>> st{lcp};
    for (int k = 1; (1 << k) <= N; k++) {
        int len = N - (1 << k) + 1;
        vector<int> row(len);
        for (int i = 0; i < len; i++)
            row[i] = min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
        st.push_back(move(row));
    }
    auto lce = [&](int i, int j) {
        if (i == n || j == m || a[i] != b[j])
            return 0;
        int x = rank[i], y = rank[n + 1 + j];
        if (x > y)
            swap(x, y);
        int k = lg[y - x];
        return min(st[k][x + 1], st[k][y - (1 << k) + 1]);
    };
    int W = min<long long>(max(n, m), L * K);
    vector<int> prev(2 * W + 1, -1);
    prev[W] = lce(0, 0);
    if (prev[W] == n && n == m) {
        cout << 0 << "\n";
        return 0;
    }
    for (int t = 1; t <= min<long long>(K, n + m); t++) {
        vector<int> next(2 * W + 1, -1);
        for (int d = -W; d <= W; d++)
            if (prev[d + W] >= 0) {
                int i = prev[d + W], j = i - d;
                for (int h = 1; h <= min<long long>(L, n - i); h++) {
                    int dd = d + h;
                    if (dd > W)
                        break;
                    int reach = i + h + lce(i + h, j);
                    if (reach == n && reach - dd == m) {
                        cout << t << "\n";
                        return 0;
                    }
                    next[dd + W] = max(next[dd + W], reach);
                }
                for (int h = 1; h <= min<long long>(L, m - j); h++) {
                    int dd = d - h;
                    if (dd < -W)
                        break;
                    int reach = i + lce(i, j + h);
                    if (reach == n && reach - dd == m) {
                        cout << t << "\n";
                        return 0;
                    }
                    next[dd + W] = max(next[dd + W], reach);
                }
            }
        prev.swap(next);
    }
    cout << "Impossible\n";
}

