    sa.sort(key=lambda i: (rank[i], rank[i + gap] if i + gap < N else -1))
    nr = [0] * N
    for j in range(1, N):
        x, y = sa[j - 1], sa[j]
        nr[y] = nr[x] + (
            (rank[x], rank[x + gap] if x + gap < N else -1)
            != (rank[y], rank[y + gap] if y + gap < N else -1)
        )
    rank = nr
    if rank[sa[-1]] == N - 1:
        break
    gap *= 2
lcp = [0] * N
h = 0
for i in range(N):
    r = rank[i]
    if not r:
        continue
    j = sa[r - 1]
    while i + h < N and j + h < N and s[i + h] == s[j + h]:
        h += 1
    lcp[r] = h
    if h:
        h -= 1
logs = [0] * (N + 1)
for i in range(2, N + 1):
    logs[i] = logs[i // 2] + 1
st = [lcp]
power = 2
while power <= N:
    prev = st[-1]
    half = power // 2
    st.append([min(prev[i], prev[i + half]) for i in range(N - power + 1)])
    power *= 2


def lce(i, j):
    if i == n or j == m or a[i] != b[j]:
        return 0
    x, y = rank[i], rank[n + 1 + j]
    if x > y:
        x, y = y, x
    k = logs[y - x]
    return min(st[k][x + 1], st[k][y - (1 << k) + 1])


start = lce(0, 0)
if start == n == m:
    print(0)
    raise SystemExit
front = {0: start}
for t in range(1, min(K, n + m) + 1):
    new = {}
    for d, i in front.items():
        j = i - d
        for h in range(1, min(L, n - i) + 1):
            dd = d + h
            reach = i + h + lce(i + h, j)
            if reach == n and reach - dd == m:
                print(t)
                raise SystemExit
            if reach > new.get(dd, -1):
                new[dd] = reach
        for h in range(1, min(L, m - j) + 1):
            dd = d - h
            reach = i + lce(i, j + h)
            if reach == n and reach - dd == m:
                print(t)
                raise SystemExit
            if reach > new.get(dd, -1):
                new[dd] = reach
    front = new
print("Impossible")

