        if (c + 1 < N)
            v.push_back(u + 1);
        if (r)
            v.push_back(u - N);
        if (r + 1 < M)
            v.push_back(u + N);
        if (p)
            v.push_back(u - M * N);
        if (p + 1 < F)
            v.push_back(u + M * N);
        return v;
    };
    while (q.size()) {
        int u = q.front();
        q.pop();
        for (int v : neighbors(u))
            if (d[v] < 0) {
