        vector<int> q{s};
        d[s] = 0;
        for (size_t i = 0; i < q.size(); i++) {
            int u = q[i];
            for (int v : g[u])
                if (d[v] == 65535) {
                    d[v] = d[u] + 1;
                    q.push_back(v);
                }
        }
        dist.push_back(move(d));
    }
