    int cid = 0;
    for (int s = 0; s < n; s++)
        if (!hub[s] && comp[s] < 0) {
            vector<int> q{s};
            comp[s] = cid;
            for (size_t i = 0; i < q.size(); i++)
                for (int v : g[q[i]])
                    if (!hub[v] && comp[v] < 0) {
                        comp[v] = cid;
                        q.push_back(v);
                    }
            cid++;
        }
    unordered_map<long long, int> cache;
    for (int z = 0; z < Q; z++) {
        int s, t;
