        --t;
        if (s > t)
            swap(s, t);
        long long key = 1LL * s * n + t;
        int ans;
        auto it = cache.find(key);
        if (it != cache.end())
            ans = it->second;
        else {
            int upper = n, lower = 0;
            for (auto &d : dist) {
                int a = d[s], b = d[t];
                upper = min(upper, a + b);
                lower = max(lower, abs(a - b));
            }
