                    for (int v : g[u])
                        if (!hub[v] && d[v] < 0) {
                            d[v] = d[u] + 1;
                            if (v == t) {
                                ans = d[v];
                                found = true;
                                break;
                            }
                            q.push_back(v);
                        }
                }
            }
            cache[key] = ans;
        }
