import sys, math, random
from array import array


def solve():
    def nums():
        for line in sys.stdin.buffer:
            for x in line.split():
                yield int(x)

    z = nums()
    n, m, Q = next(z), next(z), next(z)
    g = [[] for _ in range(n)]
    for _ in range(m):
        u, v = next(z) - 1, next(z) - 1
        g[u].append(v)
        g[v].append(u)
    h = min(n, 2 * math.isqrt(n - 1) + 2)
    selected = random.Random(20261103).sample(range(n), h)
    hub = bytearray(n)
    for s in selected:
        hub[s] = 1
    dist = []
    for s in selected:
        d = [-1] * n
        d[s] = 0
        queue = [s]
        for u in queue:
            nd = d[u] + 1
            for v in g[u]:
                if d[v] < 0:
                    d[v] = nd
                    queue.append(v)
        dist.append(array("H", d))
    comp = [-1] * n
    cid = 0
    for s in range(n):
        if hub[s] or comp[s] >= 0:
            continue
        comp[s] = cid
        queue = [s]
        for u in queue:
            for v in g[u]:
                if not hub[v] and comp[v] < 0:
                    comp[v] = cid
                    queue.append(v)
        cid += 1

    def internal(s, t, upper):
        d = [-1] * n
        d[s] = 0
        queue = [s]
        for u in queue:
            nd = d[u] + 1
            if nd >= upper:
                continue
            for v in g[u]:
                if not hub[v] and d[v] < 0:
                    d[v] = nd
                    if v == t:
                        return nd
                    queue.append(v)
        return upper

    cache = {}
    out = []
    for _ in range(Q):
        s, t = next(z) - 1, next(z) - 1
        if s > t:
            s, t = t, s
        key = s * n + t
        if key not in cache:
            upper = n
            lower = 0
            for d in dist:
                a, b = d[s], d[t]
                candidate = a + b
                if candidate < upper:
                    upper = candidate
                difference = a - b
                if difference < 0:
                    difference = -difference
                if difference > lower:
                    lower = difference
            if lower != upper and not hub[s] and not hub[t] and comp[s] == comp[t]:
                upper = internal(s, t, upper)
            cache[key] = upper
        out.append(str(cache[key]))
    print(" ".join(out))


