int main() {
    int n, m;
    cin >> n >> m;
    int V = n * m, B = V + 1;
    vector<char> a(V);
    vector<int> balls;
    for (int i = 0; i < V; i++) {
        cin >> a[i];
        if (a[i] == 'b')
            balls.push_back(i + 1);
    }
    int dr[] = {1, 0, -1, 0}, dc[] = {0, 1, 0, -1};
    vector<vector<int>> dest(4, vector<int>(B));
    for (int d = 0; d < 4; d++)
        for (int u = 0; u < V; u++)
            if (a[u] != 'w') {
                int r = u / m, c = u % m;
                while (true) {
                    int x = r + dr[d], y = c + dc[d];
                    if (x < 0 || x >= n || y < 0 || y >= m) {
                        dest[d][u + 1] = 0;
                        break;
                    }
                    if (a[x * m + y] == 'w') {
                        dest[d][u + 1] = r * m + c + 1;
                        break;
                    }
                    r = x;
                    c = y;
                }
            }
    balls.resize(3);
    auto enc = [&](vector<int> b, int d) {
        sort(b.begin(), b.end());
        return ((b[0] * B + b[1]) * B + b[2]) * 4 + d;
    };
    int total = 4 * B * B * B, start = enc(balls, 0);
    vector<unsigned char> vis(total);
    vector<int> q{start};
    vis[start] = 1;
    int steps = 0;
    size_t at = 0;
    while (at < q.size()) {
        size_t end = q.size();
        while (at < end) {
            int s = q[at++], d = s % 4, v = s / 4;
            vector<int> b(3);
            for (int j = 2; j >= 0; j--) {
                b[j] = v % B;
                v /= B;
            }
            if (!b[2]) {
                cout << steps << "\n";
                return 0;
            }
            for (int dd : {(d + 1) % 4, (d + 3) % 4}) {
                auto bb = b;
                sort(bb.begin(), bb.end(), [&](int x, int y) {
                    if (!x || !y)
                        return x > y;
                    return ((x - 1) / m * dr[dd] + (x - 1) % m * dc[dd]) >
                           ((y - 1) / m * dr[dd] + (y - 1) % m * dc[dd]);
                });
                map<int, int> used;
                vector<int> nb;
                for (int x : bb)
                    if (x) {
                        int t = dest[dd][x];
                        if (t) {
                            int cnt = used[t]++;
                            nb.push_back(t - cnt * (dr[dd] * m + dc[dd]));
                        }
                    }
                nb.resize(3);
                int key = enc(nb, dd);
                if (!vis[key]) {
                    vis[key] = 1;
                    q.push_back(key);
                }
            }
        }
        steps++;
    }
    cout << -1 << "\n";
}

