#include <bits/stdc++.h>
using namespace std;
#include <boost/multiprecision/cpp_int.hpp>
#include <boost/rational.hpp>
using I = boost::multiprecision::cpp_int;
using R = boost::rational<I>;
I gcdI(I a, I b) {
    if (a < 0)
        a = -a;
    if (b < 0)
        b = -b;
    while (b != 0) {
        I t = a % b;
        a = b;
        b = t;
    }
    return a;
}
int main() {
    string line, s;
    getline(cin, line);
    for (char c : line)
        if (!isspace(c))
            s += c;
    vector<string> terms;
    vector<int> sign;
    int side = 1, start = 0;
    for (int i = 0; i <= (int)s.size(); i++)
        if (i == (int)s.size() || s[i] == '+' || s[i] == '=') {
            terms.push_back(s.substr(start, i - start));
            sign.push_back(side);
            if (i < (int)s.size() && s[i] == '=')
                side = -1;
            start = i + 1;
        }
    int n = terms.size();
    vector<map<char, I>> atoms(n);
    set<char> elements;
    for (int j = 0; j < n; j++)
        for (int i = 0; i < (int)terms[j].size();) {
            char c = terms[j][i++];
            I count = 0;
            bool digits = false;
            while (i < (int)terms[j].size() && isdigit(terms[j][i])) {
                count = count * 10 + terms[j][i++] - '0';
                digits = true;
            }
            if (!digits)
                count = 1;
            atoms[j][c] += count;
            elements.insert(c);
        }
    vector<vector<R>> a;
    for (char c : elements) {
        vector<R> row(n);
        for (int j = 0; j < n; j++)
            row[j] = R(atoms[j][c] * sign[j]);
        row[n - 1] = -row[n - 1];
        a.push_back(row);
    }
    for (int c = 0; c < n - 1; c++) {
        int p = c;
        while (a[p][c].numerator() == 0)
            p++;
        swap(a[p], a[c]);
        R v = a[c][c];
        for (int j = c; j < n; j++)
            a[c][j] /= v;
        for (int i = 0; i < n - 1; i++)
            if (i != c) {
                v = a[i][c];
                for (int j = c; j < n; j++)
                    a[i][j] -= v * a[c][j];
            }
    }
    vector<R> x(n, R(1));
    for (int i = 0; i < n - 1; i++)
        x[i] = a[i][n - 1];
    I den = 1;
    for (auto v : x)
        den = den / gcdI(den, v.denominator()) * v.denominator();
    vector<I> ans;
    I g = 0;
    for (auto v : x) {
        I z = v.numerator() * (den / v.denominator());
        ans.push_back(z);
        g = gcdI(g, z);
    }
    for (int i = 0; i < n; i++) {
        if (i)
            cout << (sign[i] == sign[i - 1] ? " + " : " = ");
        I v = ans[i] / g;
        if (v < 0)
            v = -v;
        if (v != 1)
            cout << v;
        cout << terms[i];
    }
    cout << "\n";
}

