#include <bits/stdc++.h>
using namespace std;
struct P {
    int a, b, c, id;
};
bool exists(vector<P> x, vector<P> y, int S) {
    if (x.empty() || y.empty())
        return false;
    sort(x.begin(), x.end(), [](P a, P b) { return a.a < b.a; });
    sort(y.begin(), y.end(), [](P a, P b) { return a.a > b.a; });
    vector<int> B;
    for (auto p : y)
        B.push_back(-p.b);
    sort(B.begin(), B.end());
    B.erase(unique(B.begin(), B.end()), B.end());
    int n = B.size();
    vector<int> v1(n + 1, -1), v2(n + 1, -1), id1(n + 1, -1);
    int at = 0;
    for (auto p : x) {
        while (at < (int)y.size() && y[at].a >= S - p.a) {
            auto q = y[at++];
            int j = lower_bound(B.begin(), B.end(), -q.b) - B.begin() + 1;
            for (; j <= n; j += j & -j)
                if (q.c > v1[j]) {
                    v2[j] = v1[j];
                    v1[j] = q.c;
                    id1[j] = q.id;
                } else if (q.c > v2[j])
                    v2[j] = q.c;
        }
        int j = upper_bound(B.begin(), B.end(), p.b - S) - B.begin(), best = -1;
        for (; j; j -= j & -j)
            best = max(best, id1[j] == p.id ? v2[j] : v1[j]);
        if (best >= 0 && best >= S - p.c)
            return true;
    }
    return false;
}
int main() {
    int n;
    cin >> n;
    vector<P> g[3];
    for (int i = 0, w, a, b, c; i < n; i++) {
        cin >> w >> a >> b >> c;
        g[w / 1000000 - 1].push_back({a, b, c, i});
    }
    set<int> ans;
    for (int i = 0; i < 3; i++)
        for (int j = i; j < 3; j++) {
            int S = (i + j + 2) * 1000000;
            if (exists(g[i], g[j], S))
                ans.insert(S);
        }
    cout << ans.size() << "\n";
    for (int v : ans)
        cout << v << "\n";
}

