    need.erase(unique(need.begin(), need.end()), need.end());
    const long long M = 1000000007;
    map<int, long long> fac;
    long long f = 1;
    int at = 0;
    for (int i = 1; i <= need.back(); i++) {
        f = f * i % M;
        if (i == need[at]) {
            fac[i] = f;
            at++;
            if (at == (int)need.size())
                break;
        }
    }
    auto pw = [&](long long x, long long e) {
        long long r = 1;
        while (e) {
            if (e & 1)
                r = r * x % M;
            x = x * x % M;
            e /= 2;
        }
        return r;
    };
    long long ans = fac[n0];
    for (int x : a)
        ans = ans * fac[n0 + x] % M;
    ans = ans * pw(pw(fac[n0], M - 2), t) % M;
    cout << ans << "\n";
