#include <bits/stdc++.h>
using namespace std;
#include <boost/multiprecision/cpp_int.hpp>
using I = boost::multiprecision::cpp_int;
int n, width;
I all;
vector<I> readTree(int m) {
    int V = n + m;
    vector<vector<pair<int, int>>> g(V);
    for (int e = 0, u, v; e < V - 1; e++) {
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back({v, e});
        g[v].push_back({u, e});
    }
    vector<int> p(V, -1), pe(V), order{0};
    p[0] = 0;
    for (int i = 0; i < V; i++)
        for (auto [v, e] : g[order[i]])
            if (v != p[order[i]]) {
                p[v] = order[i];
                pe[v] = e;
                order.push_back(v);
            }
    vector<I> sub(V), parts(V - 1);
    for (int i = 0; i < n; i++)
        sub[i] = I(1) << i;
    for (int i = V - 1; i > 0; i--) {
        int u = order[i];
        parts[pe[u]] = sub[u];
        sub[p[u]] |= sub[u];
    }
    return parts;
}
void put(string &s, I x) {
    for (int i = 0; i < width; i++) {
        s += char((x & 255).convert_to<unsigned>());
        x >>= 8;
    }
}
string key(const vector<I> &parts, int a, int b) {
    vector<I> comp;
    if (a < 0)
        comp = {all};
    else if (b < 0)
        comp = {parts[a], all ^ parts[a]};
    else {
        I A = parts[a], B = parts[b], both = A & B;
        if (both == 0)
            comp = {A, B, all ^ A ^ B};
        else if (both == A)
            comp = {A, B ^ A, all ^ B};
        else
            comp = {B, A ^ B, all ^ A};
    }
    sort(comp.begin(), comp.end());
    string s;
    for (I x : comp)
        if (x != 0) {
            set<I> split;
            for (I A : parts) {
                I u = A & x, v = x ^ u;
                if (u != 0 && v != 0 && (u & (u - 1)) != 0 && (v & (v - 1)) != 0)
                    split.insert(u < v ? u : v);
            }
            put(s, x);
            int z = split.size();
            s += char(z & 255);
            s += char(z >> 8);
            for (I a : split)
                put(s, a);
        }
    return s;
}
int main() {
    int m1, m2, K;
    cin >> n >> m1 >> m2 >> K;
    width = (n + 7) / 8;
    all = (I(1) << n) - 1;
    auto a = readTree(m1), b = readTree(m2);
    if (key(a, -1, -1) == key(b, -1, -1)) {
        cout << 0 << "\n";
        return 0;
    }
    for (int k = 1; k <= K; k++) {
        unordered_map<string, long long> count;
        for (int i = 0; i < (int)a.size(); i++)
            if (k == 1)
                count[key(a, i, -1)]++;
            else
                for (int j = i + 1; j < (int)a.size(); j++)
                    count[key(a, i, j)]++;
        long long answer = 0;
        for (int i = 0; i < (int)b.size(); i++)
            if (k == 1) {
                auto it = count.find(key(b, i, -1));
                if (it != count.end())
                    answer += it->second;
            } else
                for (int j = i + 1; j < (int)b.size(); j++) {
                    auto it = count.find(key(b, i, j));
                    if (it != count.end())
                        answer += it->second;
                }
        if (answer) {
            cout << k << "\n" << answer << "\n";
            return 0;
        }
    }
    cout << -1 << "\n";
}

#include <bits/stdc++.h>
using namespace std;
struct P {
    int x, y;
    bool operator<(const P &o) const {
        return tie(x, y) < tie(o.x, o.y);
    }
};
int cross(P a, P b, P c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}
int main() {
    int n, m;
    cin >> n >> m;
    vector<P> a(n), b(m);
    for (auto &p : a)
        cin >> p.x >> p.y;
    for (auto &p : b)
        cin >> p.x >> p.y;
    map<pair<int, int>, vector<P>> groups;
    for (auto p : a)
        for (auto q : b)
            groups[{q.x - p.x, q.y - p.y}].push_back(p);
    bitset<801> answer;
    for (auto &entry : groups) {
        auto points = entry.second;
        sort(points.begin(), points.end());
        for (int base = 0; base + 2 < (int)points.size(); base++) {
            P p = points[base];
            vector<P> v(points.begin() + base + 1, points.end());
            sort(v.begin(), v.end(), [&](P x, P y) {
                int z = cross(p, x, y);
                if (z)
                    return z > 0;
                return (x.x - p.x) * (x.x - p.x) + (x.y - p.y) * (x.y - p.y) <
                       (y.x - p.x) * (y.x - p.x) + (y.y - p.y) * (y.y - p.y);
            });
            int s = v.size();
            vector<vector<bitset<801>>> d(s, vector<bitset<801>>(s));
            for (int i = 0; i < s; i++)
                for (int j = i + 1; j < s; j++) {
                    int ar = cross(p, v[i], v[j]);
                    if (ar > 0)
                        d[i][j].set(ar);
                }
            for (int j = 1; j < s; j++)
                for (int i = 0; i < j; i++)
                    if (d[i][j].any()) {
                        answer |= d[i][j];
                        for (int k = j + 1; k < s; k++) {
                            int ar = cross(p, v[j], v[k]);
                            if (ar > 0 && cross(v[i], v[j], v[k]) > 0)
                                d[j][k] |= d[i][j] << ar;
                        }
                    }
        }
    }
    answer.reset(0);
    cout << answer.count() << "\n";
    for (int i = 1; i <= 800; i++)
        if (answer[i])
            cout << i << "\n";
}

