#include <bits/stdc++.h>
using namespace std;
long long pw(long long a, long long b, long long m) {
    long long r = 1;
    while (b) {
        if (b & 1)
            r = r * a % m;
        a = a * a % m;
        b /= 2;
    }
    return r;
}
int main() {
    int n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> a(n, vector<long long>(n + 1));
    for (int i = 0; i < n; i++)
        cin >> a[i][n];
    for (int j = 0; j < n; j++)
        for (int i = 0; i < n; i++)
            cin >> a[i][j];
    for (int c = 0; c < n; c++) {
        int p = c;
        while (a[p][c] % m == 0)
            p++;
        swap(a[p], a[c]);
        long long inv = pw(a[c][c] % m, m - 2, m);
        for (int j = c; j <= n; j++)
            a[c][j] = a[c][j] * inv % m;
        for (int i = 0; i < n; i++)
            if (i != c) {
                long long v = a[i][c] % m;
                for (int j = c; j <= n; j++)
                    a[i][j] = (a[i][j] % m - v * a[c][j] % m + m) % m;
            }
    }
    for (int i = 0; i < n; i++)
        cout << (i ? " " : "") << a[i][n];
    cout << "\n";
}

