#include <bits/stdc++.h>
using namespace std;
#include <boost/multiprecision/cpp_int.hpp>
#include <boost/rational.hpp>
using I = boost::multiprecision::cpp_int;
using R = boost::rational<I>;
I gcdI(I a, I b) {
    while (b != 0) {
        I t = a % b;
        a = b;
        b = t;
    }
    return a;
}
I lcmI(I a, I b) {
    return a / gcdI(a, b) * b;
}
I ten(int n) {
    I v = 1;
    while (n--)
        v *= 10;
    return v;
}
R parse(string s) {
    int exp = 0;
    auto e = s.find_first_of("eE");
    if (e != string::npos) {
        exp = stoi(s.substr(e + 1));
        s = s.substr(0, e);
    }
    bool neg = false;
    if (s[0] == '-' || s[0] == '+') {
        neg = s[0] == '-';
        s = s.substr(1);
    }
    auto p = s.find('.');
    int digits = p == string::npos ? 0 : s.size() - p - 1;
    I num = 0;
    for (char c : s)
        if (c != '.')
            num = num * 10 + c - '0';
    if (neg)
        num = -num;
    int scale = digits - exp;
    return scale >= 0 ? R(num, ten(scale)) : R(num * ten(-scale));
}
string format(I w, I D) {
    bool neg = w < 0;
    if (neg)
        w = -w;
    I q = w * 100 / D, rem = w * 100 % D;
    if (rem * 2 >= D)
        q++;
    I whole = q / 100;
    int cents = (q % 100).convert_to<int>();
    return string(neg && q != 0 ? "-" : "") + whole.convert_to<string>() + "." +
           (cents < 10 ? "0" : "") + to_string(cents);
}
struct Row {
    R x, y, yd;
    array<R, 4> inc;
};
int main() {
    string t;
    cin >> t;
    R w1 = parse(t);
    cin >> t;
    R w2 = parse(t);
    cin >> t;
    R b = parse(t);
    cin >> t;
    R alpha = parse(t);
    I rounds;
    size_t k;
    cin >> rounds >> k;
    vector<Row> rows(k);
    I D = lcmI(w1.denominator(), w2.denominator());
    for (auto &r : rows) {
        cin >> t;
        r.x = parse(t);
        cin >> t;
        r.y = parse(t);
        cin >> t;
        r.yd = parse(t);
        for (int v = 0; v < 2; v++) {
            R error = r.yd - R(v == 0 ? 1 : -1);
            R factor = alpha * error * error / R(2);
            r.inc[v * 2] = factor * r.x;
            r.inc[v * 2 + 1] = factor * r.y;
        }
        for (auto v : r.inc)
            D = lcmI(D, v.denominator());
    }
    vector<array<I, 7>> data;
    for (auto &r : rows) {
        I den = lcmI(lcmI(r.x.denominator(), r.y.denominator()), b.denominator());
        array<I, 7> z;
        z[0] = r.x.numerator() * (den / r.x.denominator());
        z[1] = r.y.numerator() * (den / r.y.denominator());
        z[2] = b.numerator() * (den / b.denominator()) * D;
        for (int i = 0; i < 4; i++)
            z[3 + i] = r.inc[i].numerator() * (D / r.inc[i].denominator());
        data.push_back(z);
    }
    I W1 = w1.numerator() * (D / w1.denominator()),
      W2 = w2.numerator() * (D / w2.denominator());
    while (rounds > 0) {
        for (auto &r : data) {
            int i = W1 * r[0] + W2 * r[1] + r[2] >= 0 ? 3 : 5;
            W1 += r[i];
            W2 += r[i + 1];
        }
        rounds--;
    }
    cout << format(W1, D) << " " << format(W2, D) << "\n";
}

