int main() {
    int n, m;
    cin >> n >> m;
    if (n < m)
        swap(n, m);
    if (m == 1) {
        cout << min(n, 2) << "\n";
        return 0;
    }
    if (m == 2) {
        cout << 2 * n << "\n";
        return 0;
    }
    unordered_map<string, int> dp, next;
    dp[string(m + 1, char(0))] = 0;
    int best = 1;
    for (int r = 0; r < n; r++)
        for (int c = 0; c < m; c++) {
            next.clear();
            for (auto &entry : dp) {
                const string &s = entry.first;
                int value = entry.second, left = (unsigned char)s[0],
                    up = (unsigned char)s[c + 1], inc = (left != 0) + (up != 0),
                    nf = s.size() - m - 1;
                if (!inc && (r || c)) {
                    auto [it, inserted] = next.try_emplace(s, value);
                    if (!inserted)
                        it->second = max(it->second, value);
                }
                if (left && left == up)
                    continue;
                bool hasEnd = false;
                for (int j = m + 1; j < (int)s.size(); j++)
                    if (s[j] & 2)
                        hasEnd = true;
                for (int right = 0; right <= int(c + 1 < m); right++)
                    for (int down = 0; down <= int(r + 1 < n); down++) {
                        int degree = inc + right + down;
                        if (!degree || degree > 2 || (r == 0 && c == 0 && degree != 1))
                            continue;
                        if (degree == 2 && ((left && right) || (up && down)))
                            continue;
                        int endpoint = (r == 0 && c == 0) ? 1 : degree == 1 ? 2 : 0;
                        if (endpoint == 2 && hasEnd)
                            continue;
                        array<int, 14> slots{}, flags{};
                        for (int j = 0; j <= m; j++)
                            slots[j] = (unsigned char)s[j];
                        for (int j = 0; j < nf; j++)
                            flags[j] = (unsigned char)s[m + 1 + j];
                        int label = left ? left : up ? up : nf + 1, merged = endpoint;
                        if (left)
                            merged |= flags[left - 1];
                        if (up)
                            merged |= flags[up - 1];
                        if (left && up) {
                            for (int j = 0; j <= m; j++)
                                if (slots[j] == up)
                                    slots[j] = left;
                            label = left;
                        }
                        flags[label - 1] = merged;
                        slots[0] = right ? label : 0;
                        slots[c + 1] = down ? label : 0;
                        bool present = false, any = false;
                        for (int j = 0; j <= m; j++) {
                            present |= slots[j] == label;
                            any |= slots[j] != 0;
                        }
                        if (!present) {
                            if (merged == 3 && !any)
                                best = max(best, value + 1);
                            continue;
                        }
                        array<int, 14> mapping{};
                        int labels = 0;
                        string key(m + 1, char(0));
                        for (int j = 0; j <= m; j++) {
                            int x = slots[j];
                            if (x && !mapping[x]) {
                                mapping[x] = ++labels;
                                key += char(flags[x - 1]);
                            }
                            key[j] = char(mapping[x]);
                        }
                        auto [it, inserted] = next.try_emplace(key, value + 1);
                        if (!inserted)
                            it->second = max(it->second, value + 1);
                    }
            }
            dp.swap(next);
        }
    cout << best << "\n";
}

