        auto add = [&](int u, int v, int c) {
            int x = g[u].size(), y = g[v].size();
            g[u].push_back({v, y, c});
            g[v].push_back({u, x, 0});
        };
        int dr[] = {0, 0, -1, -1, 1, 1}, dc[] = {-1, 1, 0, 1, -1, 0};
        for (int r = 0; r < n; r++)
