                    for (int k = 0; k < 6; k++) {
                        int x = r + dr[k], y = c + dc[k];
                        if (x >= 0 && x < n && y >= 0 && y < m && a[x][y] == '.')
                            add(2 * u + 1, 2 * (x * m + y), 2);
