using namespace std;
int locate(const string &t, const string &p, int start, int limit) {
    vector<int> pi(p.size());
    for (int i = 1, j = 0; i < (int)p.size(); i++) {
        while (j && p[i] != p[j])
            j = pi[j - 1];
        if (p[i] == p[j])
            j++;
        pi[i] = j;
    }
    for (int i = start, j = 0; i < limit; i++) {
        while (j && t[i] != p[j])
            j = pi[j - 1];
        if (t[i] == p[j])
            j++;
        if (j == (int)p.size())
            return i + 1;
    }
    return -1;
}
bool match(string s, string t) {
    if (s.find('*') == string::npos)
        return s == t;
    int start = 0, limit = t.size();
    vector<string> parts;
    string cur;
    for (char c : s)
        if (c == '*') {
            parts.push_back(cur);
            cur = "";
        } else
            cur += c;
    parts.push_back(cur);
    if (s.front() != '*') {
        auto p = parts.front();
        if (t.substr(0, p.size()) != p)
            return false;
        start = p.size();
        parts.front() = "";
    }
    if (s.back() != '*') {
        auto p = parts.back();
        if (p.size() > t.size() || t.substr(t.size() - p.size()) != p)
            return false;
        limit -= p.size();
        parts.back() = "";
    }
    if (start > limit)
        return false;
    for (string p : parts)
        if (p.size()) {
            start = locate(t, p, start, limit);
            if (start < 0)
