import sys


def locate(t, p, start, limit):
    pi = [0] * len(p)
    j = 0
    for i in range(1, len(p)):
        while j and p[i] != p[j]:
            j = pi[j - 1]
        if p[i] == p[j]:
            j += 1
        pi[i] = j
    j = 0
    for i in range(start, limit):
        while j and t[i] != p[j]:
            j = pi[j - 1]
        if t[i] == p[j]:
            j += 1
        if j == len(p):
            return i + 1
    return -1


def match(s, t):
    if "*" not in s:
        return s == t
    parts = s.split("*")
    start = 0
    limit = len(t)
    if not s.startswith("*"):
        p = parts[0]
        if not t.startswith(p):
            return False
        start = len(p)
        parts[0] = ""
    if not s.endswith("*"):
        p = parts[-1]
        if not t.endswith(p):
            return False
        limit -= len(p)
        parts[-1] = ""
    if start > limit:
        return False
    for p in parts:
        if p:
            start = locate(t, p, start, limit)
            if start < 0:
                return False
    return True


