#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n);
    vector<int> deg(n);
    for (int i = 0, u, v; i < m; i++) {
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(v);
        g[v].push_back(u);
        deg[u]++;
        deg[v]++;
    }
    vector<set<int>> bucket(n);
    for (int i = 0; i < n; i++)
        bucket[deg[i]].insert(i);
    vector<bool> removed(n);
    vector<int> core(n);
    int cur = 0, k = 0;
    for (int t = 0; t < n; t++) {
        while (bucket[cur].empty())
            cur++;
        int u = *bucket[cur].begin();
        bucket[cur].erase(u);
        removed[u] = true;
        k = max(k, cur);
        core[u] = k;
        for (int v : g[u])
            if (!removed[v]) {
                bucket[deg[v]].erase(v);
                deg[v]--;
                bucket[deg[v]].insert(v);
                cur = min(cur, deg[v]);
            }
    }
    vector<int> order(n), p(n), sz(n, 1);
    iota(order.begin(), order.end(), 0);
    iota(p.begin(), p.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) { return core[a] > core[b]; });
    auto find = [&](int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    };
    vector<bool> active(n);
    long long ans = 0;
    int best = 0;
    for (int i = 0; i < n;) {
        int j = i;
        while (j < n && core[order[j]] == core[order[i]]) {
            int u = order[j++];
            active[u] = true;
            best = max(best, 1);
            for (int v : g[u])
                if (active[v]) {
                    int a = find(u), b = find(v);
                    if (a != b) {
                        if (sz[a] < sz[b])
                            swap(a, b);
                        p[b] = a;
                        sz[a] += sz[b];
                        best = max(best, sz[a]);
                    }
                }
        }
        ans = max(ans, 1LL * best * core[order[i]]);
        i = j;
    }
    cout << ans << "\n";
}

