using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<int> ds(n);
    iota(ds.begin(), ds.end(), 0);
    auto find = [&](int x) {
        while (ds[x] != x) {
            ds[x] = ds[ds[x]];
            x = ds[x];
        }
        return x;
    };
    vector<vector<pair<int, int>>> g(n);
    vector<pair<int, int>> queries;
    for (int i = 1, u, v; i <= m; i++) {
        cin >> u >> v;
        --u;
        --v;
        int a = find(u), b = find(v);
        if (a != b) {
            ds[a] = b;
            g[u].push_back({v, i});
            g[v].push_back({u, i});
            queries.push_back({-1, -1});
        } else
            queries.push_back({u, v});
    }
    int L = 1;
    while ((1 << L) <= n)
        L++;
    vector<vector<int>> up(L, vector<int>(n)), mx(L, vector<int>(n));
    vector<int> p(n, -1), dep(n), order;
    for (int root = 0; root < n; root++)
        if (p[root] < 0) {
            p[root] = root;
            up[0][root] = root;
            size_t begin = order.size();
            order.push_back(root);
            for (size_t i = begin; i < order.size(); i++) {
                int u = order[i];
                for (auto [v, w] : g[u])
                    if (v != p[u]) {
                        p[v] = u;
                        up[0][v] = u;
                        mx[0][v] = w;
                        dep[v] = dep[u] + 1;
                        order.push_back(v);
                    }
            }
        }
    for (int j = 1; j < L; j++)
        for (int v = 0; v < n; v++) {
            int a = up[j - 1][v];
            up[j][v] = up[j - 1][a];
            mx[j][v] = max(mx[j - 1][v], mx[j - 1][a]);
        }
    for (auto [x, y] : queries) {
        if (x < 0) {
            cout << "Mukyu\n";
            continue;
        }
        int ans = 0;
        if (dep[x] < dep[y])
            swap(x, y);
        int diff = dep[x] - dep[y];
        for (int j = 0; j < L; j++)
            if (diff >> j & 1) {
                ans = max(ans, mx[j][x]);
                x = up[j][x];
            }
        if (x != y) {
            for (int j = L - 1; j >= 0; j--)
                if (up[j][x] != up[j][y]) {
                    ans = max({ans, mx[j][x], mx[j][y]});
                    x = up[j][x];
                    y = up[j][y];
                }
            ans = max({ans, mx[0][x], mx[0][y]});
        }
        cout << ans << "\n";
    }
}

