        for (auto [dx, dy] : vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
            int a = x + dx, c = y + dy;
            if (a >= 0 && a < n && c >= 0 && c < n && h[a * n + c] < h[b])
                b = a * n + c;
        }
        if (b != u) {
            balls[b] += balls[u];
            balls[u] = 0;
        }
    }
    int cnt = 0, best = 0;
    for (int x : balls)
        if (x) {
            cnt++;
            best = max(best, x);
        }
    cout << cnt << " " << best << "\n";
}

