#include <boost/rational.hpp>
using I = boost::multiprecision::cpp_int;
using R = boost::rational<I>;
I number(string s) {
    I x = 0;
    for (char c : s)
        x = x * 10 + c - '0';
    return x;
}
int main() {
    int n;
    string s, ts;
    cin >> n >> s >> ts;
    I target = number(ts);
    string ops = "+-*/";
    vector<tuple<int, string, string>> answers;
    auto test = [&](vector<string> v, string o) {
        R sum(0), term(number(v[0]));
        for (int i = 0; i < (int)o.size(); i++) {
            R x(number(v[i + 1]));
            char c = o[i];
            if (c == '*')
                term *= x;
            else if (c == '/') {
                if (x.numerator() == 0)
                    return;
                term /= x;
            } else {
                sum += term;
                term = c == '+' ? x : -x;
            }
        }
        if (sum + term != R(target))
            return;
        string expr = v[0], key;
        for (int i = 0; i < (int)o.size(); i++) {
            expr += o[i] + v[i + 1];
            key += char('0' + ops.find(o[i]));
        }
        answers.push_back({o.size(), key, expr});
    };
    test({s}, "");
    for (int i = 1; i < n; i++)
        for (char c : ops)
            test({s.substr(0, i), s.substr(i)}, string(1, c));
    for (int i = 1; i < n; i++)
        for (int j = i + 1; j < n; j++)
            for (char c : ops)
                for (char d : ops)
                    test({s.substr(0, i), s.substr(i, j - i), s.substr(j)},
                         string(1, c) + d);
    sort(answers.begin(), answers.end());
    for (auto &[count, key, expr] : answers)
        cout << expr << "\n";
}

