                    term /= x
                else:
                    total += term
                    term = x if op == 0 else -x
            if valid and total + term == target:
                expr = parts[0] + "".join(
                    ops[o] + p for o, p in zip(choices, parts[1:])
                )
                answers.append((count, choices, expr))
