#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<int> a(n * n);
    char c;
    for (int &i : a) {
        cin >> c;
        i = c - '0';
    }
    int V = n * n;
    if (!a[0]) {
        cout << 0 << "\n";
        return 0;
    }
    using U = unsigned long long;
    vector<U> adj(V);
    U mask = 0, color = 0;
    for (int u = 0; u < V; u++)
        if (a[u]) {
            mask |= 1ULL << u;
            int x = u / n, y = u % n;
            if ((x + y) % 2)
                color |= 1ULL << u;
            for (auto [dx, dy] :
                 vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
                int r = x + dx, s = y + dy;
                if (r >= 0 && r < n && s >= 0 && s < n && a[r * n + s])
                    adj[u] |= 1ULL << (r * n + s);
            }
        }
    int best = 1;
    function<void(int, U, int)> dfs = [&](int u, U used, int len) {
        best = max(best, len);
        U allowed = (mask & ~used) | (1ULL << u), seen = 0, front = 1ULL << u;
        while (front) {
            U bit = front & -front;
            front -= bit;
            int v = __builtin_ctzll(bit);
            seen |= bit;
            front |= adj[v] & allowed & ~seen;
            front &= ~seen;
        }
        int same = __builtin_popcountll(seen & (color >> u & 1 ? color : ~color)),
            other = __builtin_popcountll(seen) - same;
        int bound = min(same, other + 1) + min(other, same);
        if (len + bound - 1 <= best)
            return;
        vector<int> next;
        U q = adj[u] & ~used;
        while (q) {
            int v = __builtin_ctzll(q);
            q &= q - 1;
            next.push_back(v);
        }
        sort(next.begin(), next.end(), [&](int a, int b) {
            return __builtin_popcountll(adj[a] & ~used) <
                   __builtin_popcountll(adj[b] & ~used);
        });
        for (int v : next)
            dfs(v, used | (1ULL << v), len + 1);
    };
    dfs(0, 1, 1);
    cout << best << "\n";
}

