                    cost = 1;
                } else if (x == b) {
                    b = h;
                    cost = 1;
                } else if (x == c) {
                    c = h;
                    cost = 1;
                }
                int lo = min(x, other), hi = max(x, other),
                    key = a | b << 4 | c << 8 | lo << 12 | hi << 16, nv = value + cost;
                if (nv < d[key]) {
                    d[key] = nv;
                    if (cost)
                        q.push_back(key);
                    else
                        q.push_front(key);
                }
            }
    }
    return d;
}
int main() {
    array<int, 16> board;
    array<int, 15> pos{};
