        for (auto [dx, dy] : vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
            int a = x + dx, b = y + dy;
            if (a >= 0 && a < 4 && b >= 0 && b < 4)
                adj[i].push_back(a * 4 + b);
        }
    }
    bool solved = true;
    for (int i = 0; i < 14; i++)
        if (board[i] != i + 1)
            solved = false;
    if (solved) {
        cout << 0 << "\n";
        return 0;
    }
    auto db1 = build({8, 9, 10}), db2 = build({11, 12, 13});
    auto bottomCode = [&]() {
        int key = 0;
        for (int i = 8; i < 16; i++)
            key |= (board[i] ? board[i] - 8 : 0) << (3 * (i - 8));
        return key;
    };
    auto unpack = [](int key) {
        array<int, 8> a{};
        for (int i = 0; i < 8; i++)
            a[i] = (key >> (3 * i)) & 7;
        return a;
    };
    int goal = 0;
    for (int i = 0; i < 6; i++)
        goal |= (i + 1) << (3 * i);
    unordered_map<int, int> bottom;
    bottom[goal] = 0;
    queue<int> q;
    q.push(goal);
    while (q.size()) {
        int key = q.front();
        q.pop();
        auto a = unpack(key);
        int value = bottom[key];
        for (int h = 0; h < 8; h++)
            if (!a[h])
                for (int vv : adj[h + 8])
                    if (vv >= 8) {
                        int v = vv - 8;
                        if (a[v]) {
                            int next = key ^ (a[v] << (3 * h)) ^ (a[v] << (3 * v));
                            if (!bottom.count(next)) {
                                bottom[next] = value + 1;
                                q.push(next);
                            }
                        }
                    }
    }
    int upper = bottom[bottomCode()], md[15][16] = {};
    for (int t = 1; t <= 14; t++)
        for (int u = 0; u < 16; u++)
            md[t][u] = abs(u / 4 - (t - 1) / 4) + abs(u % 4 - (t - 1) % 4);
    auto heuristic = [&](int h1, int h2, int top) {
        int common = h1 << 12 | h2 << 16;
        int h = db1[pos[9] | pos[10] << 4 | pos[11] << 8 | common] +
                db2[pos[12] | pos[13] << 4 | pos[14] << 8 | common] + top;
        if (!top)
            h = max(h, min(bottom[bottomCode()], h + 2));
        return h;
    };
    using U = unsigned long long;
    U initial = 0;
    for (int i = 0; i < 16; i++)
        initial |= U(board[i]) << (4 * i);
    unordered_map<U, int> seen;
    function<int(int, int, int, int, int, U, int, int)> dfs =
        [&](int g, int bound, int h1, int h2, int top, U code, int avoidH, int avoidV) {
            int h = heuristic(h1, h2, top);
            if (g + h > bound)
                return g + h;
            if (!h)
                return -1;
            if (!top && g + bottom[bottomCode()] <= bound)
                return -1;
            int best = 100;
            vector<array<int, 7>> options;
            for (auto [hole, other] : vector<pair<int, int>>{{h1, h2}, {h2, h1}})
                for (int v : adj[hole]) {
                    int tile = board[v];
                    if (!tile || (hole == avoidH && v == avoidV))
                        continue;
                    int a = min(v, other), b = max(v, other),
                        nt = top + (tile <= 8 ? md[tile][hole] - md[tile][v] : 0);
                    board[hole] = tile;
                    board[v] = 0;
                    pos[tile] = hole;
                    int nh = heuristic(a, b, nt);
                    board[v] = tile;
                    board[hole] = 0;
                    pos[tile] = v;
                    if (g + 1 + nh <= bound)
                        options.push_back({nh, hole, v, tile, a, b, nt});
                    else
                        best = min(best, g + 1 + nh);
                }
            sort(options.begin(), options.end());
            for (auto op : options) {
                auto [hh, hole, v, tile, a, b, nt] = op;
                U nc = code ^ (U(tile) << (4 * hole)) ^ (U(tile) << (4 * v));
                int ng = g + 1;
                auto it = seen.find(nc);
                if (it != seen.end() && it->second <= ng)
                    continue;
                seen[nc] = ng;
                board[hole] = tile;
                board[v] = 0;
                pos[tile] = hole;
                int result = dfs(ng, bound, a, b, nt, nc, v, hole);
                board[v] = tile;
                board[hole] = 0;
                pos[tile] = v;
                if (result == -1)
                    return -1;
                best = min(best, result);
            }
            return best;
        };
    int bound = heuristic(holes[0], holes[1], 0);
    while (bound < upper) {
        seen.clear();
        seen[initial] = 0;
        int result = dfs(0, bound, holes[0], holes[1], 0, initial, -1, -1);
        if (result == -1) {
            cout << bound << "\n";
            return 0;
        }
        bound = result;
    }
    cout << upper << "\n";
}

