import sys
from collections import deque

board = list(map(int, sys.stdin.read().split()))
if board[:14] == list(range(1, 15)):
    print(0)
    raise SystemExit
adj = [[] for _ in range(16)]
for u in range(16):
    r, c = divmod(u, 4)
    for x, y in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
        if 0 <= x < 4 and 0 <= y < 4:
            adj[u].append(x * 4 + y)


def build(goal):
    d = bytearray([255]) * (1 << 20)
    done = bytearray(1 << 20)
    start = goal[0] | goal[1] << 4 | goal[2] << 8 | 14 << 12 | 15 << 16
    d[start] = 0
    q = deque([start])
    while q:
        code = q.popleft()
        if done[code]:
            continue
        done[code] = 1
        p0 = code & 15
        p1 = code >> 4 & 15
        p2 = code >> 8 & 15
        h1 = code >> 12 & 15
        h2 = code >> 16 & 15
        value = d[code]
        for h, other in ((h1, h2), (h2, h1)):
            for x in adj[h]:
                if x == other:
                    continue
                a, b, c = p0, p1, p2
                cost = 0
                if x == a:
                    a = h
                    cost = 1
                elif x == b:
                    b = h
                    cost = 1
                elif x == c:
                    c = h
                    cost = 1
                lo, hi = (x, other) if x < other else (other, x)
                key = a | b << 4 | c << 8 | lo << 12 | hi << 16
                nv = value + cost
                if nv < d[key]:
                    d[key] = nv
                    if cost:
                        q.append(key)
                    else:
                        q.appendleft(key)
    return d


db1 = build((8, 9, 10))
db2 = build((11, 12, 13))
goal = (1, 2, 3, 4, 5, 6, 0, 0)
bottom = {goal: 0}
q = deque([goal])
while q:
    state = q.popleft()
    value = bottom[state]
    for h, tile in enumerate(state):
        if tile:
            continue
        for vv in adj[h + 8]:
            if vv < 8:
                continue
            v = vv - 8
            if state[v]:
                nxt = list(state)
                nxt[h], nxt[v] = nxt[v], 0
                nxt = tuple(nxt)
                if nxt not in bottom:
                    bottom[nxt] = value + 1
                    q.append(nxt)
md = [
    [abs(u // 4 - (tile - 1) // 4) + abs(u % 4 - (tile - 1) % 4) for u in range(16)]
    for tile in range(1, 15)
]
pos = [0] * 15
for u, tile in enumerate(board):
    if tile:
        pos[tile] = u
holes = sorted(u for u, tile in enumerate(board) if not tile)
code = sum(tile << (4 * u) for u, tile in enumerate(board))


def bottom_distance():
    return bottom[tuple(tile - 8 if tile else 0 for tile in board[8:])]


upper = bottom_distance()


def heuristic(h1, h2, top):
    common = h1 << 12 | h2 << 16
    h = (
        db1[pos[9] | pos[10] << 4 | pos[11] << 8 | common]
        + db2[pos[12] | pos[13] << 4 | pos[14] << 8 | common]
        + top
    )
    if top == 0:
        h = max(h, min(bottom_distance(), h + 2))
    return h


def dfs(g, bound, h1, h2, top, code, avoid):
    h = heuristic(h1, h2, top)
    if g + h > bound:
        return g + h
    if h == 0:
        return -1
    if top == 0 and g + bottom_distance() <= bound:
        return -1
    best = 100
    options = []
    for hole, other in ((h1, h2), (h2, h1)):
        for v in adj[hole]:
            tile = board[v]
            if not tile or (hole, v) == avoid:
                continue
            a, b = (v, other) if v < other else (other, v)
            nt = top + (md[tile - 1][hole] - md[tile - 1][v] if tile <= 8 else 0)
            board[hole] = tile
            board[v] = 0
            pos[tile] = hole
            nh = heuristic(a, b, nt)
            board[v] = tile
            board[hole] = 0
            pos[tile] = v
            if g + 1 + nh <= bound:
                options.append((nh, hole, v, tile, a, b, nt))
            else:
                best = min(best, g + 1 + nh)
    options.sort()
    for nh, hole, v, tile, a, b, nt in options:
        nc = code ^ (tile << (4 * hole)) ^ (tile << (4 * v))
        ng = g + 1
        if seen.get(nc, 100) <= ng:
            continue
        seen[nc] = ng
        board[hole] = tile
        board[v] = 0
        pos[tile] = hole
        result = dfs(ng, bound, a, b, nt, nc, (v, hole))
        board[v] = tile
        board[hole] = 0
        pos[tile] = v
        if result == -1:
            return -1
        best = min(best, result)
    return best


bound = heuristic(*holes, 0)
while bound < upper:
    seen = {code: 0}
    result = dfs(0, bound, *holes, 0, code, (-1, -1))
    if result == -1:
        print(bound)
        break
    bound = result
else:
    print(upper)

