int main() {
    int X, Y, T;
    cin >> X >> Y >> T;
    int W = (X + 63) / 64;
    using U = unsigned long long;
    vector<vector<U>> a(Y + 2, vector<U>(W)), b = a;
    for (int y = 1; y <= Y; y++)
        for (int x = 0, v; x < X; x++) {
            cin >> v;
            if (v)
                a[y][x / 64] |= 1ULL << (x % 64);
        }
    for (int t = 0; t < T; t++) {
        for (int y = 1; y <= Y; y++)
            for (int j = 0; j < W; j++) {
                U c0 = 0, c1 = 0, c2 = 0, c3 = 0;
                auto add = [&](U v) {
                    U k = c0 & v;
                    c0 ^= v;
                    U l = c1 & k;
                    c1 ^= k;
                    U m = c2 & l;
                    c2 ^= l;
                    c3 ^= m;
                };
                for (int r = y - 1; r <= y + 1; r++) {
                    U v = a[r][j], l = (v << 1) | (j ? a[r][j - 1] >> 63 : 0),
                      rr = (v >> 1) | (j + 1 < W ? a[r][j + 1] << 63 : 0);
                    add(l);
                    add(rr);
                    if (r != y)
                        add(v);
                }
                U eq2 = ~c3 & ~c2 & c1 & ~c0, eq3 = ~c3 & ~c2 & c1 & c0;
                b[y][j] = eq3 | (a[y][j] & eq2);
                if (j == W - 1 && X % 64)
                    b[y][j] &= (1ULL << (X % 64)) - 1;
            }
        a.swap(b);
    }
    for (int y = 1; y <= Y; y++) {
        for (int x = 0; x < X; x++)
            cout << ((a[y][x / 64] >> (x % 64)) & 1);
        cout << "\n";
    }
}

